import{_ as r,o as e,c as a,a2 as n}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"外観","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/appearance.md","filePath":"ja-JP/user-guide/settings/appearance.md","lastUpdated":1785993908000}'),o={name:"ja-JP/user-guide/settings/appearance.md"};function s(i,t,l,g,p,d){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="外観" tabindex="-1">外観 <a class="header-anchor" href="#外観" aria-label="Permalink to &quot;外観&quot;">​</a></h1><p>サイドバーの一番下、<a href="./about.html">バージョン情報</a> の上に固定表示されています。2 つのグループがあります: <strong>テーマモード</strong> とテーマピッカー自体です。</p><h2 id="テーマモード" tabindex="-1">テーマモード <a class="header-anchor" href="#テーマモード" aria-label="Permalink to &quot;テーマモード&quot;">​</a></h2><p>3 つのカードがあり、クリックで切り替えます:</p><ul><li><strong>ライト</strong> — 単一の固定テーマで、下のグリッドがライト系のテーマだけに絞り込まれます。</li><li><strong>ダーク</strong> — 同様に、ダーク系のテーマだけに絞り込まれます。</li><li><strong>システムに従う</strong>(ライト/ダークの分割プレビュー) — 単一の固定テーマを使う代わりに、Windows がライトモードのときと、ダークモードのときとで、それぞれ選んだ 2 つのテーマを Lertaro が切り替えます。Windows 自体の設定を切り替えると、再起動不要で即座に更新されます。</li></ul><p><strong>ライト</strong> と <strong>ダーク</strong> を切り替えると、それぞれの系統で最後に選択していたテーマに戻ります(<strong>システムに従う</strong> 自体がライト/ダークのペアに使う、記憶された選択と同じものです)。そのため、行き来しても両側の選択が失われることはありません。</p><h2 id="インターフェーステーマ" tabindex="-1">インターフェーステーマ <a class="header-anchor" href="#インターフェーステーマ" aria-label="Permalink to &quot;インターフェーステーマ&quot;">​</a></h2><p>上で <strong>ライト</strong> または <strong>ダーク</strong> が選択されている場合、単一のカードグリッドにその系統のテーマだけが表示されます。<strong>システムに従う</strong> が選択されている場合、グリッドは <strong>ライトテーマ</strong> と <strong>ダークテーマ</strong> の 2 つに分かれます。それぞれのデフォルトは、その系統に一致するテーマのうち最初にインストールされているものになります。そもそもどのテーマが存在するかは、どのテーマプラグインがインストールされているかに完全に依存します。</p><p>各テーマは名前だけでなくカードとして表示されます。クイック検索ウィンドウの小さなモックアップ(検索ボックスと、選択状態のものを含む数行の結果)がそのテーマ自身の配色でレンダリングされ、切り替える前に実際の見た目を確認できます。現在有効なテーマのカードにはチェックマークバッジが表示されます。</p><p>組み込みおよびバンドルされているテーマプラグイン:</p><ul><li><strong>CoreExtensions</strong>(組み込み) — Light、Dark、Nord、Sakura、Cyberpunk。</li><li><strong>AnimeThemes</strong>(バンドル、インストールおよび有効化されている場合) — Neon Genesis、Sakura Bloom、Weathering Blue。</li><li><strong>Curated Themes</strong>(バンドル、インストールおよび有効化されている場合) — 10 種類のライト/ダークペア: Glacier、Terracotta、Forest、Amethyst、Crimson、Graphite、Indigo、Mint、Champagne、Amber。</li></ul><p>他のテーマプラグインも、同じ方法でグリッドにカードを追加できます。</p>',12)])])}const c=r(o,[["render",s]]);export{h as __pageData,c as default};
